  function shuffle(arr) {
    var a = arr.slice();
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  function buildDeck(mode) {
    if (mode === 'kids') {
      return shuffle(ALL_QUESTIONS.filter(function (q) { return q.difficulty === 'easy' || q.difficulty === 'medium'; }));
    }
    return shuffle(ALL_QUESTIONS.filter(function (q) { return q.difficulty === 'medium' || q.difficulty === 'hard'; }));
  }

  function diffLabel(d) {
    if (d === 'easy') return 'קל';
    if (d === 'hard') return 'מתקדם';
    return 'בינוני';
  }

  function setRoadPercent(p) {
    var v = Math.max(0, Math.min(100, p));
    var s = v + '%';
    roadTrack.style.setProperty('--p', s);
    if (roadTrackDock) roadTrackDock.style.setProperty('--p', s);
    roadTrack.setAttribute('aria-valuenow', String(Math.round(v)));
  }

