      '<div class="quiz-card__head">' +
      '<div class="quiz-streak-strip" role="status" aria-live="polite">' +
      '<span class="quiz-streak-milestones">3 נכונות ברצף - חגיגה קטנה · 5 ברצף - חגיגה גדולה</span>' +
      '<span class="quiz-streak-now is-zero" id="quizStreakNow">רצף נוכחי: עדיין לא</span>' +
      '</div>' +
      '<span class="quiz-cat">' + escapeHtml(q.catTag) + '<span class="quiz-diff"> · ' + escapeHtml(diffLabel(q.difficulty)) + '</span></span>' +
      '<div class="quiz-q" id="qq">' + escapeHtml(q.q) + '</div></div>' +
      '<div class="quiz-opts" id="opts">' + optsHtml + '</div>' +
      '<div class="quiz-card__foot">' +
      '<div class="quiz-fact" id="factEl" aria-live="polite">' + escapeHtml(q.fact) + '</div>' +
      '</div></div>';

    document.getElementById('factEl').classList.remove('is-visible');

    syncQuizStreakBanner();

    mount.querySelectorAll('.quiz-opt-btn').forEach(function (btn) {
      btn.addEventListener('click', function () {
        if (answered) return;
        if (Date.now() < quizAnswersUnlockAt) return;
        answered = true;
        var i = parseInt(btn.getAttribute('data-i'), 10);
        var picked = q.opts[i];
        var buttons = mount.querySelectorAll('.quiz-opt-btn');
        buttons.forEach(function (b, bi) {
          b.disabled = true;
          var opt = q.opts[bi];
          var check = b.querySelector('.opt-check');
          var cross = b.querySelector('.opt-cross');
          if (opt.correct) {
            b.classList.add('is-correct');
            if (check) check.classList.add('is-show');
          } else if (bi === i && !opt.correct) {
            b.classList.add('is-picked-wrong');
            if (cross) cross.classList.add('is-show');
          }
        });
        var wasCorrect = picked.correct;
        if (wasCorrect) {
          score++;
          sessionStreak++;
        } else {
          sessionStreak = 0;
        }
        document.getElementById('factEl').classList.add('is-visible');
        var tot = QUESTIONS.length;
        var rem = tot - idx - 1;
        setProgressLabels('שאלה ' + (idx + 1) + '/' + tot + ' · ' + score + ' נק׳' + (rem > 0 ? ' · עוד ' + rem : ''));

        syncQuizStreakBanner();

        feedbackAfterAnswer(wasCorrect, wasCorrect ? sessionStreak : 0);

        advanceTimer = setTimeout(function () {
          advanceTimer = null;
          idx++;
          if (idx >= QUESTIONS.length) showEnd();
          else {
            updateProgress();
            renderQuestion();
          }
        }, advanceDelayMs());
      });
    });

    updateProgress();
  }

  function showEnd() {
    clearAdvanceTimer();
    showPlayingChrome(false);
    mount.innerHTML = '';
    gameIntro.classList.add('hidden');
    var total = QUESTIONS.length;
    setRoadPercent(100);
    setProgressLabels('סיימתם · ' + score + '/' + total + ' תשובות נכונות');

    finalScore.textContent = score + '/' + total;
    endModeChip.textContent = audience === 'kids' ? '🧒 סיכום מסלול ילדים' : '🧑‍🏫 סיכום מסלול הורים';

    var pct = total ? Math.round((score / total) * 100) : 0;
    var stars = pct >= 85 ? '⭐⭐⭐' : pct >= 65 ? '⭐⭐' : pct >= 40 ? '⭐' : '✨';
    endStars.textContent = stars;

    endTitle.textContent = 'סיימתם את המסלול!';

    if (pct >= 85) {
      finalMsg.textContent = 'מדריכי אלפים לשעבר - ידע מצוין לאוסטריה!';
      finalSub.textContent = 'ממש לפני הטיול: נסו למצוא חלק מהעובדות על השלטים והנופים מהחלון.';
    } else if (pct >= 65) {
      finalMsg.textContent = 'מקצוענים בדרך - יש לכם בסיס חזק מאוד.';
      finalSub.textContent = 'עוד סיבוב בעוד יום יכול להפוך את זה למושלם (ואין כאן כישלון - רק תרגול).';
    } else if (pct >= 40) {
      finalMsg.textContent = 'יופי של סיבוב - כל שאלה מחברת אתכם קצת יותר ליעד.';
      finalSub.textContent = 'בטיול האמיתי אתם תזכרו את מה שלמדתם כאן בלי לשים לב.';
    } else {
      finalMsg.textContent = 'זה היה סיבוב חימום מצוין!';
      finalSub.textContent = 'משחק טריוויה הוא כמו ניווט בכביש שעוקף - עכשיו אתם כבר מכירים את השילוט. רוצים סיבוב נוסף עם מסלול אחר?';
    }

    gameEnd.classList.add('is-visible');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function escapeHtml(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function escapeAttr(s) {
    return escapeHtml(s).replace(/'/g, '&#39;');
  }

  function startGame(mode) {
    audience = mode;
    QUESTIONS = buildDeck(mode);
    idx = 0;
    score = 0;
    sessionStreak = 0;
    modeChip.textContent = mode === 'kids' ? 'מסלול: ילדים · קל + בינוני' : 'מסלול: הורים · בינוני + מתקדם';
    setRoadPercent((1 / QUESTIONS.length) * 100);
    renderQuestion();
  }

  document.getElementById('btnPickChooseGame').addEventListener('click', function () {
    pickInstructions.classList.add('hidden');
    pickGameChoice.classList.remove('hidden');
    setProgressLabels('בוחרו מסלול למטה כדי להתחיל');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  document.getElementById('pickKids').addEventListener('click', function () { startGame('kids'); });
  document.getElementById('pickParents').addEventListener('click', function () { startGame('parents'); });

  document.getElementById('btnRestartRun').addEventListener('click', function () { restartSameTrack(); });
  document.getElementById('btnNewGameRun').addEventListener('click', function () { resetToPicker(); });

  document.getElementById('replayBtn').addEventListener('click', function (e) {
    e.preventDefault();
    resetToPicker();
  });
})();
